def is_good_triple(x, y, z):
    numerator = (x + 1)**y
    denominator = x**z + 1
    if denominator == 0:
        # Should not happen since x >= 1, z >= 1
        return False
    return numerator % denominator == 0

good_triples = []
X_values = [1, 2, 3]
Y_values = range(1, 100)
Z_values = range(1, 100)

for x in X_values:
    for y in Y_values:
        for z in Z_values:
            if is_good_triple(x, y, z):
                good_triples.append((x, y, z))

print("Total good triples found:", len(good_triples))
# Print the first 50 and last 50 for inspection, as there might be many.
# Let's just print the count and maybe a few examples if the list is too long.
if len(good_triples) < 100:
    print("List of good triples:")
    for triple in good_triples:
        print(triple)
else:
    print("First 50 good triples:")
    for triple in good_triples[:50]:
        print(triple)
    print("...")
    print("Last 50 good triples:")
    for triple in good_triples[-50:]:
        print(triple)

