import math
from sympy import is_power_of_prime

def is_power_of_3(n):
    if n <= 0:
        return False
    if n == 1:
        return True
    while n % 3 == 0:
        n //= 3
    return n == 1

solutions = []
# We only need to check odd z >= 1 because if z is even (z>=2), 2^z + 1 is 2 (mod 3) and thus not divisible by 3.
# The problem context implies 1 <= z < 100.
for z in range(1, 100):
    if z % 2 == 0:
        continue

    N = pow(2, z) + 1

    if is_power_of_3(N):
        # Calculate k such that N = 3^k
        k = round(math.log(N, 3))
        solutions.append((z, k))

print(solutions)
